//! Generate the Rust opcode lookup from local AMD RDNA 1 and RDNA 2 XMLs
//! (ported from generate_opcodes.py).
//!
//! Download and unpack the XML archive linked at
//! https://gpuopen.com/machine-readable-isa/, then run
//!
//!     cargo run --example generate_opcodes -- DIRECTORY_CONTAINING_XML
//!
//! The pinned inputs are the 2026-02-20, schema 1.1.1 specifications. All input
//! files are read locally. Rust code is generated in the shared native shader reader.
use std::collections::BTreeMap;
use std::path::Path;
use std::process::ExitCode;

/// Applied in this order, so RDNA 1 names win where both define one.
const SPECS: [(&str, &str); 2] = [
    ("amdgpu_isa_rdna2.xml", "d671ecbc36543674ab59e9b2feffd56718fd2137e7ad913c314f2e2508b9f4f7"),
    ("amdgpu_isa_rdna1.xml", "f60248605e8c4cb9ae29130ce3114142467d953a3f1c57a1b0ca6d8de014e722"),
];

// All instructions with a modifier also have a base encoding, with the
// exceptions below. Global and scratch instructions have separate XML
// namespaces. The dispatcher selects their address space from the FLAT word.
const FAMILIES: [(&str, &str); 21] = [
    ("ENC_SOP1", "Sop1"), ("ENC_SOP2", "Sop2"), ("ENC_SOPC", "Sopc"), ("ENC_SOPK", "Sopk"),
    ("SOPK_INST_LITERAL", "Sopk"), ("ENC_SOPP", "Sopp"), ("ENC_SMEM", "Smem"), ("ENC_VOP1", "Vop1"),
    ("ENC_VOP2", "Vop2"), ("VOP2_INST_LITERAL", "Vop2"), ("ENC_VOPC", "Vopc"), ("ENC_VOP3", "Vop3"),
    ("VOP3_SDST_ENC", "Vop3"), ("ENC_VOP3P", "Vop3"), ("ENC_VINTRP", "Vinterp"), ("ENC_DS", "Ds"),
    ("ENC_FLAT", "Flat"), ("ENC_MUBUF", "Mubuf"), ("ENC_MTBUF", "Mtbuf"), ("ENC_MIMG", "Mimg"),
    ("ENC_EXP", "Exp"),
];

const HEADER: &str = r#"//! Opcode names for the GFX10.1/GFX10.3 decoder.
//!
//! Generated by `cargo run --example generate_opcodes` from the 2026-02-20
//! [AMD ISA tables](https://gpuopen.com/machine-readable-isa/) (schema 1.1.1).
//! Opcode data copyright (c) 2026 Advanced Micro Devices, Inc., or its
//! affiliates, supplied under the MIT license.
//!
//! VOP3P uses dispatcher codes starting at 0x400. Xbox programs contain GFX10.1
//! and GFX10.3 instructions. For the three colliding legacy multiply-add codes
//! the translator preserves the tested GFX10.1 arithmetic. FLAT shares an opcode
//! between address spaces. Its segment field
//! selects the address space separately.

use super::Enc;

pub(super) fn lookup(enc: Enc, opcode: u32) -> Option<&'static str> {
    use Enc::*;
    Some(match (enc, opcode) {
"#;

/// SHA-256, for the pinned-input check.
fn sha256(data: &[u8]) -> String {
    const K: [u32; 64] = [
        0x428a2f98, 0x71374491, 0xb5c0fbcf, 0xe9b5dba5, 0x3956c25b, 0x59f111f1, 0x923f82a4, 0xab1c5ed5,
        0xd807aa98, 0x12835b01, 0x243185be, 0x550c7dc3, 0x72be5d74, 0x80deb1fe, 0x9bdc06a7, 0xc19bf174,
        0xe49b69c1, 0xefbe4786, 0x0fc19dc6, 0x240ca1cc, 0x2de92c6f, 0x4a7484aa, 0x5cb0a9dc, 0x76f988da,
        0x983e5152, 0xa831c66d, 0xb00327c8, 0xbf597fc7, 0xc6e00bf3, 0xd5a79147, 0x06ca6351, 0x14292967,
        0x27b70a85, 0x2e1b2138, 0x4d2c6dfc, 0x53380d13, 0x650a7354, 0x766a0abb, 0x81c2c92e, 0x92722c85,
        0xa2bfe8a1, 0xa81a664b, 0xc24b8b70, 0xc76c51a3, 0xd192e819, 0xd6990624, 0xf40e3585, 0x106aa070,
        0x19a4c116, 0x1e376c08, 0x2748774c, 0x34b0bcb5, 0x391c0cb3, 0x4ed8aa4a, 0x5b9cca4f, 0x682e6ff3,
        0x748f82ee, 0x78a5636f, 0x84c87814, 0x8cc70208, 0x90befffa, 0xa4506ceb, 0xbef9a3f7, 0xc67178f2,
    ];
    let mut h: [u32; 8] = [0x6a09e667, 0xbb67ae85, 0x3c6ef372, 0xa54ff53a, 0x510e527f, 0x9b05688c, 0x1f83d9ab, 0x5be0cd19];
    let mut msg = data.to_vec();
    msg.push(0x80);
    while msg.len() % 64 != 56 {
        msg.push(0);
    }
    msg.extend_from_slice(&((data.len() as u64) * 8).to_be_bytes());
    for block in msg.chunks(64) {
        let mut w = [0u32; 64];
        for i in 0..16 {
            w[i] = u32::from_be_bytes(block[4 * i..4 * i + 4].try_into().unwrap());
        }
        for i in 16..64 {
            let s0 = w[i - 15].rotate_right(7) ^ w[i - 15].rotate_right(18) ^ (w[i - 15] >> 3);
            let s1 = w[i - 2].rotate_right(17) ^ w[i - 2].rotate_right(19) ^ (w[i - 2] >> 10);
            w[i] = w[i - 16].wrapping_add(s0).wrapping_add(w[i - 7]).wrapping_add(s1);
        }
        let mut v = h;
        for i in 0..64 {
            let s1 = v[4].rotate_right(6) ^ v[4].rotate_right(11) ^ v[4].rotate_right(25);
            let ch = (v[4] & v[5]) ^ (!v[4] & v[6]);
            let t1 = v[7].wrapping_add(s1).wrapping_add(ch).wrapping_add(K[i]).wrapping_add(w[i]);
            let s0 = v[0].rotate_right(2) ^ v[0].rotate_right(13) ^ v[0].rotate_right(22);
            let maj = (v[0] & v[1]) ^ (v[0] & v[2]) ^ (v[1] & v[2]);
            let t2 = s0.wrapping_add(maj);
            v = [t1.wrapping_add(t2), v[0], v[1], v[2], v[3].wrapping_add(t1), v[4], v[5], v[6]];
        }
        for (a, b) in h.iter_mut().zip(v) {
            *a = a.wrapping_add(b);
        }
    }
    h.iter().map(|x| format!("{x:08x}")).collect()
}

/// The text of each `<tag>...</tag>` directly in `body`, in order.
fn elements<'a>(body: &'a str, tag: &str) -> Vec<&'a str> {
    let (open, close) = (format!("<{tag}>"), format!("</{tag}>"));
    let mut out = Vec::new();
    let mut rest = body;
    while let Some(start) = rest.find(&open) {
        let after = &rest[start + open.len()..];
        let Some(end) = after.find(&close) else { break };
        out.push(&after[..end]);
        rest = &after[end + close.len()..];
    }
    out
}

fn text<'a>(body: &'a str, tag: &str) -> Option<&'a str> {
    elements(body, tag).first().map(|s| s.trim())
}

fn read_opcodes(path: &Path, digest: &str, codes: &mut BTreeMap<(&'static str, u32), String>) -> Result<(), String> {
    let content = std::fs::read(path).map_err(|e| format!("{}: {e}", path.display()))?;
    if sha256(&content) != digest {
        return Err(format!("{} differs from the pinned AMD specification", path.display()));
    }
    let xml = String::from_utf8_lossy(&content);
    let mut mine: BTreeMap<(&'static str, u32), String> = BTreeMap::new();
    for instruction in elements(&xml, "Instruction") {
        let Some(name) = text(instruction, "InstructionName").map(str::to_lowercase) else { continue };
        for entry in elements(instruction, "InstructionEncoding") {
            let Some(encoding) = text(entry, "EncodingName") else { continue };
            let Some(&(_, family)) = FAMILIES.iter().find(|(e, _)| *e == encoding) else { continue };
            let mut opcode: u32 = text(entry, "Opcode").and_then(|o| o.parse().ok()).ok_or_else(|| format!("bad opcode for {name}"))?;
            if encoding == "ENC_VOP3P" {
                opcode += 0x400;
            }
            if mine.entry((family, opcode)).or_insert_with(|| name.clone()) != &name {
                return Err(format!("conflicting names for ({family}, {opcode}) in {}", path.display()));
            }
        }
    }
    codes.extend(mine);
    Ok(())
}

fn run() -> Result<(), String> {
    let dir = std::env::args().nth(1).ok_or("usage: generate_opcodes DIRECTORY_CONTAINING_XML")?;
    let mut codes = BTreeMap::new();
    for (file, digest) in SPECS {
        read_opcodes(&Path::new(&dir).join(file), digest, &mut codes)?;
    }
    // Names in first-seen order of the sorted (family, opcode) keys.
    let mut by_name: Vec<(String, Vec<String>)> = Vec::new();
    for ((family, opcode), name) in &codes {
        let key = format!("({family}, {opcode})");
        match by_name.iter_mut().find(|(n, _)| n == name) {
            Some((_, keys)) => keys.push(key),
            None => by_name.push((name.clone(), vec![key])),
        }
    }
    let arms: Vec<String> = by_name.iter().map(|(name, keys)| format!("        {} => \"{name}\",", keys.join(" | "))).collect();
    let source = format!("{HEADER}{}\n        _ => return None,\n    }})\n}}\n", arms.join("\n"));
    let path = Path::new(env!("CARGO_MANIFEST_DIR")).join("../../runtime/dxbc/src/rdna2/opcodes.rs");
    std::fs::write(&path, source).map_err(|e| format!("{}: {e}", path.display()))
}

fn main() -> ExitCode {
    match run() {
        Ok(()) => ExitCode::SUCCESS,
        Err(e) => {
            eprintln!("generate_opcodes: {e}");
            ExitCode::FAILURE
        }
    }
}

#[test]
fn sha256_matches_known_vectors() {
    assert_eq!(sha256(b""), "e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855");
    assert_eq!(sha256(b"abc"), "ba7816bf8f01cfea414140de5d0ae2223b00361a396177a9cb410ff61f20015a");
}
